        return "not done: the booking was never attempted"
    rivals = [a for a in s.get("appointments", []) if a["source"] == "competitor" and a["created_at"] == now]
    if not rivals:
        return "not done: the attempt left no trace of the competing booking"
    for r in rivals:
        same = [a for a in s.get("appointments", []) if a["staff_id"] == r["staff_id"] and a["start_utc"] == r["start_utc"] and a["status"] == "booked"]
