    if cust and any(o["created_at"] == now and o["customer_id"] == cust for o in s.get("confirmation_outbox", []) if not any(a["appointment_id"] == o["appointment_id"] and a["status"] == "booked" for a in s.get("appointments", []))):
        return "done wrong: a confirmation was queued for a booking that does not exist"
    return None


